	@Test
	void normalsAreGuardedOnlyWithATrustedRunnerUp() {
		LmdbNativeAdaptiveArbitration.Priced<String> winner = pricedArm("winner", 0, 15_000_000.0, 20_000_000.0, 64);
		LmdbNativeAdaptiveArbitration.Priced<String> trusted = pricedArm("backup", 1, 5_000_000.0, 6_000_000.0, 64);
		LmdbNativeAdaptiveArbitration.Priced<String> unmeasured = pricedArm("green", 2, 1_000_000.0, 2_000_000.0, 1);
		LmdbNativeAdaptiveArbitration.DispatchPlan.Normal<String> normal = new LmdbNativeAdaptiveArbitration.DispatchPlan.Normal<>(
				winner.candidate(), winner.prediction(), "test");

		LmdbNativeAdaptiveArbitration.DispatchPlan<String> unguarded = LmdbNativeAdaptiveArbitration.maybeGuard(
				normal, List.of(winner, unmeasured), new LmdbNativeAdaptiveArbitration.HedgeContext(HEDGE, true,
						false));
		assertSame(normal, unguarded, "an under-evidenced rival cannot back a rescue");

		LmdbNativeAdaptiveArbitration.DispatchPlan<String> guarded = LmdbNativeAdaptiveArbitration.maybeGuard(normal,
				List.of(winner, trusted, unmeasured),
				new LmdbNativeAdaptiveArbitration.HedgeContext(HEDGE, true, false));
		LmdbNativeAdaptiveArbitration.DispatchPlan.Guarded<String> plan = assertInstanceOf(
				LmdbNativeAdaptiveArbitration.DispatchPlan.Guarded.class, guarded);
		assertSame(normal, plan.normal());
		assertSame(trusted.candidate(), plan.backup());
		assertEquals((long) (winner.prediction().high99Nanos() * 1.25), plan.triggerNanos());

		LmdbNativeHedgeConfig guardOff = new LmdbNativeHedgeConfig(true, false, HEDGE.launchOverheadNanos(),
				HEDGE.interferenceFraction(), HEDGE.evidenceWeight(), HEDGE.contentionDiscount(),
				HEDGE.maxConcurrentHedges(), HEDGE.maxHedgesPerQuery(), HEDGE.overshootQuarantineFactor(),
				HEDGE.exchangePages(), HEDGE.exchangePageRows(), HEDGE.guardMinTriggerNanos(),
				HEDGE.guardTriggerMargin(), HEDGE.guardUnpricedTriggerFactor(), HEDGE.guardRemainingQuantile(),
				HEDGE.guardBackupQuantile(), HEDGE.guardMinBackupEvidence());
		assertSame(normal, LmdbNativeAdaptiveArbitration.maybeGuard(normal, List.of(winner, trusted),
				new LmdbNativeAdaptiveArbitration.HedgeContext(guardOff, true, false)),
				"the normalGuard gate alone disables arming");
	}

